typedef struct {
    uint8_t type    : 4;
    uint8_t version : 2;
    uint8_t         : 2;
    uint8_t size;
    espnow_frame_head_t frame_head;
    uint8_t dest_addr[6];
    uint8_t src_addr[6];
    uint8_t payload[0];
} __attribute__((packed))

typedef struct {
    uint8_t type;
    uint8_t group_id[6];
    uint8_t addrs_num;
    uint8_t addrs_list[0][6];
}

typedef struct {
    wifi_pkt_rx_ctrl_t rx_ctrl; /**< metadata header */
    espnow_data_t data;
}

